6	export type Item = {
7	  type: string;
8	  material?: string;
9	  enchantment?: number;
10	  cursed?: boolean;
11	};
12	
13	const PROCESSING_FEE = 5;
14	
15	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	};
22	
23	const basePremiumOf = (item: Item): number =>
24	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
25	
26	export const quote = (customer: Customer, items: Item[]): number => {
27	  const policyBasePremium = items.reduce(
28	    (sum, item) => sum + basePremiumOf(item),
29	    0,
30	  );
31	  return policyBasePremium + PROCESSING_FEE;
32	};
33	
34	export const claim = (): number => {
35	  return undefined as unknown as number;
36	};
